(function(){
const S=(title,copy,options,answer,correct,wrong)=>({title,copy,options,answer,correct,wrong});
const L=(knowledge,goal,visual,stages,cross)=>({knowledge,goal,visual,stages,cross,verified:true});
const lessons={
'eng7b:0:0':L('动物特征、喜好与理由：用外形、习性和证据介绍动物','能用 fur、wings、tail、paws、gentle、clever、dangerous 等词描述动物；能用 Why do you like…? / Because… 说明理由，并区分可观察事实与个人感受。',{kind:'animal-evidence',label:'切换动物证据卡，观察“身体结构—行为—形容词—理由”怎样连成完整描述'},[
S('概念讲授：描述动物要有可观察证据','介绍动物可按“类别—外形—行为—评价—理由”组织。形容词放在名词前，如 a clever dolphin，也可放在 be 后，如 Dolphins are clever。because 后要给事实或经历，不能只把评价词重复一遍。'),
S('正例1：从身体结构推到运动方式','A penguin has short legs and strong flippers. It cannot fly, but it swims fast. I like penguins because they move well in cold water. “flippers—swims”构成结构与运动证据。',['Penguins have strong flippers and swim well.','A penguin have wing and fly fast.','Penguins is swim in water.'],0,'正确：复数主语、have和运动证据一致。','先核对主语单复数，再核对身体结构与真实行为。'),
S('正例2：用行为证据支持评价','Elephants are helpful and social. They use their trunks to carry things and communicate with the herd. 评价 helpful/social 后都有具体行为支撑。',['Elephants are social because they communicate with their herd.','Elephants are social because social is good.','An elephants are helpful because it fly.'],0,'正确：原因是可观察行为，不是重复形容词。','because 后应补事实；elephants 是复数，不用 an。'),
S('反例与易错点：喜欢不等于随意贴标签','“I like tigers because they are cute”可以表达感受，但若任务要求科学介绍，还需证据。把 dangerous 理解成“坏”也错；危险描述的是风险，不是道德判断。',['Tigers are powerful hunters; keep a safe distance.','Tigers are bad, so facts are unnecessary.','A tiger are danger animal.'],0,'正确：描述能力和风险，不给动物贴道德标签。','用 powerful/dangerous 描述特征，并补充证据和安全边界。'),
S('教材型练习：完成动物信息卡','为海豚填写：body—smooth body and fins；ability—swim and communicate；quality—clever and social。再用两句英语回答 Why do you like dolphins?',['Dolphins have fins and communicate in groups. I like them because they are clever and social.','Dolphin has a fins. I like it because dolphin.','Dolphins are clever because clever.'],0,'正确：复数形式、代词和because理由都与信息卡对应。','检查 dolphins/they/them 的复数一致，并让理由包含信息。'),
S('解释理由：为什么先观察再选形容词？','形容词是对证据的概括。看到“合作照顾幼崽”才可推断 social/caring；看到“能解决取食问题”才可推断 clever。先选评价再硬找证据，容易形成偏见。'),
S('跨学科迁移：动物运动观察与数据报告','观察同一动物10秒内移动距离，记录身体结构、距离和时间，计算平均速度；再用英语报告结构如何帮助运动。生物解释结构功能，数学处理数据，英语表达结论。'),
S('掌握检测与小结','选择一组事实，写出动物名称、两个特征、一个行为和带because的喜好理由；必须保持单复数一致，并指出哪句话是事实、哪句话是感受。',['Otters have webbed feet and swim well. I like them because they play and work together.','An otters has foot. I like because cute.','Otters are good because I say so.'],0,'通过：事实、评价、理由及复数一致关系完整。','尚未通过：回到“观察证据→形容词→because理由”的顺序。')
],{subject:'生物与数学',title:'英语 × 生物 × 数学：动物运动观察报告',copy:'选择一种动物，记录身体结构；测量10秒内移动距离并计算平均速度；最后用英文说明“结构—运动—数据”之间的联系。',labels:['观察结构与运动','记录距离和时间并计算','用英语报告证据与结论'],options:['记录结构、距离和时间，算出速度后用完整英语句解释','只写animal和fast两个词','只看视频，不记录数据'],success:'完成：身体结构解释运动方式，距离和时间形成速度证据，英语把证据组织成可核查报告。'}),
'eng7b:0:1':L('动物在人类与生态中的作用：从文本证据提出保护行动','能从短文提取动物的作用、面临的风险和保护措施；能用 help、protect、provide、lose、need 等词建立“作用—问题—行动”证据链，并区分事实与无依据推断。',{kind:'animal-role',label:'切换动物角色卡，追踪“它做什么—遇到什么问题—我们能做什么”'},[
S('概念讲授：阅读保护文本要找三类证据','阅读时分别标出 role（动物的作用）、threat（威胁）和 action（保护行动）。例如 bees help plants produce fruit；pesticides may harm bees；planting diverse flowers provides food。三类信息不能互相替代。'),
S('正例1：导盲犬帮助人的方式','Guide dogs help people with visual impairments travel safely. They learn routes, stop at kerbs and avoid obstacles. “help”后面必须说明帮助对象和具体行为。',['Guide dogs help people travel safely by avoiding obstacles.','Guide dogs are helpful because dogs are helpful.','Guide dogs helps all person fly.'],0,'正确：对象、行为和结果都来自可核查证据。','第三人称复数用help；不要加入文本没有的能力。'),
S('正例2：蜜蜂与食物生产的联系','Bees carry pollen between flowers, helping many plants make seeds and fruit. If bee numbers fall, some crops may produce less. 这是生态过程和可能结果，不是“蜜蜂直接制造水果”。',['Bees move pollen, so many plants can produce fruit.','Bees make fruit inside their bodies.','One bees carry pollens every plant.'],0,'正确：花粉传递连接蜜蜂活动与植物结果。','不要把帮助授粉改成直接制造；注意bee/bees。'),
S('反例与易错点：保护口号不能代替行动','“Protect animals!”只是态度。可执行行动要写对象、地点、步骤和结果，如 keep rubbish out of the river to protect water birds。放生外来动物也可能破坏生态，不能一概称为保护。',['清理河岸垃圾并记录水鸟活动变化','随意把宠物放进自然保护区','只画一张Save Animals海报'],0,'正确：行动有对象、步骤和可观察结果。','保护措施还要符合当地生态规则，不能只凭善意。'),
S('教材型练习：完成作用—风险—行动表','阅读：Sea turtles may eat plastic bags because they look like jellyfish. Plastic can block their stomachs. People can reduce single-use plastic and clean beaches. 依次填写三列。',['作用/对象：海龟；风险：误食塑料；行动：减塑并清理海滩','风险：海龟吃水母；行动：增加塑料袋','作用：塑料保护海龟；行动：把垃圾埋进沙里'],0,'正确：风险因果与两项行动均能回到原文。','不要把正常食物当风险，也不要反转塑料的危害。'),
S('解释理由：为什么保护建议必须由证据推出？','同一种行动对不同物种和地点可能结果不同。先确认动物需求与威胁，再选择能改变风险变量的行动；最后记录前后变化，才能判断行动是否有效。'),
S('跨学科迁移：校园生物多样性小调查','在固定路线记录三类动物的出现次数和环境条件；用表格比较“有花植物区”和“硬化地面区”的观察数据，再用英语写一条证据和一条谨慎结论，不把相关性说成必然因果。'),
S('掌握检测与小结','根据“校园花园观察到12只蜜蜂，水泥操场只观察到2只”选择最严谨报告；指出数字支持了什么、还不能证明什么，并提出下一次需要统一的观察时段、路线长度和持续时间。',['We observed more bees in the garden. Flowers may provide food; observe at the same time and for the same duration next time.','Flowers certainly create bees because 12 is bigger than 2.','There are no bees on hard ground anywhere.'],0,'通过：数据、可能解释和控制条件均清楚。','尚未通过：观察差异不等于证明唯一因果，要说明限制。')
],{subject:'生物与数据科学',title:'英语 × 生态调查：用数据支持保护建议',copy:'沿同样长度的两条校园路线，在相同时间各观察10分钟，记录动物种类、数量和环境；比较数据并用英语写“证据—可能原因—行动建议”。',labels:['统一路线与观察时间','记录并比较物种数据','用英语写谨慎结论与行动'],options:['控制观察条件、保留原始记录，再提出与风险对应的行动','只去一次就断言永久规律','先写保护口号再编数据'],success:'完成：生态观察提供数据，统计比较呈现差异，英语区分事实、可能解释和行动建议。'}),
'eng7b:0:2':L('Wh问句、描述性形容词与名词复数：准确询问动物信息','能根据所需信息选择 what、where、why、how、how many；能正确使用 do/does、is/are和动词原形；能掌握常见复数及不规则复数，并在口语中处理功能词弱读。',{kind:'animal-language-lab',label:'改变“想知道的信息”，观察问词、助动词、形容词和复数怎样联动'},[
S('概念讲授：先判断答案类型，再选择问词','问动物是什么用 What；栖息地用 Where；原因用 Why；方式用 How；数量用 How many。一般现在时行为问句用 do/does + 主语 + 动词原形；be问句则把is/are移到主语前。'),
S('正例1：不同答案对应不同问词','Where do pandas live? — In mountain forests. Why do they eat bamboo? — Because it is widely available in their habitat. How many pandas are there? — The answer needs a number.',['Where→地点；Why→原因；How many→数量','Where→原因；Why→数量；How many→地点','三个问题都用What回答'],0,'正确：问词由预期答案类型决定。','先遮住问句，只看答案类型，再选择问词。'),
S('正例2：单数主语与复数主语的结构','What does a koala eat? — It eats leaves. What do koalas eat? — They eat leaves. does已经承担第三人称标记，后面的eat必须用原形。',['What does a koala eat? / What do koalas eat?','What does a koala eats? / What do koalas eats?','What a koala do eat? / Koalas eats what?'],0,'正确：does+原形，do+复数主语，陈述句再变化动词。','问句和答句分开检查，不要重复添加-s。'),
S('反例与易错点：复数不总是直接加-s','one mouse—two mice，one sheep—two sheep，one child—two children。fish 可表示同种多条鱼；fishes 常强调不同种类。形容词不随名词变复数，不能说 beautifuls animals。',['two mice; three sheep; clever animals','two mouses; three sheeps; clevers animals','two mouse; three sheepes; cleveres animal'],0,'正确：不规则复数和形容词形式都正确。','建立单复数配对卡；形容词本身不加复数词尾。'),
S('教材型练习：把答案改写成正确问题','答案依次为 “In Africa.” “Because they need water.” “About twenty.” “It moves quietly.” 选择四个正确问句。',['Where do they live? Why do they stay near rivers? How many are there? How does it move?','What do they live? Where because? How much animals? How it moves?','Where does they live? Why they do stay? How many is? How does it moves?'],0,'正确：地点、原因、数量和方式分别匹配，助动词结构正确。','检查does/do后的动词原形，以及How many后的复数概念。'),
S('解释理由：为什么功能词常弱读但不能省略？','自然口语中 do、does、a、the 等常比内容词轻，但它们仍标明疑问结构、时态或限定关系。完全省略会变成不完整句；每个词都同样重又会掩盖信息焦点。'),
S('跨学科迁移：用分类数据设计动物问答','给12张动物卡按栖息地、食性和足数分类。先用How many统计每组数量，再用Where/What/How提问特征；同伴根据问句定位卡片，并核对复数形式和数据。'),
S('掌握检测与小结','为“three mice live near the field and move quietly at night”设计地点、数量、方式三个问题，并选出复数与助动词都正确的一组。',['Where do the mice live? How many mice are there? How do they move?','Where does the mouses lives? How much mice? How they moves?','Where are the mouse live? How many mouse is? How does they move?'],0,'通过：问词、do结构、不规则复数和答案类型全部匹配。','尚未通过：先确定答案类型，再检查do/does和mouse/mice。')
],{subject:'数学与分类',title:'英语 × 数据分类：动物卡片问答实验',copy:'把12张动物卡按栖息地、食性或足数分类，统计每组数量；用Where、What、How、How many提出可由卡片数据回答的问题。',labels:['选择分类标准并分组','统计数量并核对复数','设计问句让同伴定位数据'],options:['分类、统计后再用对应Wh问句提取信息','只背问词中文意思','不看数据随意猜数量'],success:'完成：分类标准产生数据，复数表达数量，Wh问句准确提取地点、特征、方式与数量。'}),
'eng7b:1:0':L('校园规则与标志：用祈使句和情态动词说明地点、行为与后果','能听懂并表达 hallway、classroom、library、dining hall 等场所规则；能用动词原形祈使句、Don’t、can’t和must，把规则标志翻译成清楚、可执行的英语。',{kind:'rule-sign-lab',label:'切换校园地点和行为，观察标志、英语规则与安全结果怎样对应'},[
S('概念讲授：规则必须说明“在哪里、做什么、为什么”','肯定祈使句以动词原形开头，如 Walk in the hallway；否定祈使句用 Don’t + 原形，如 Don’t run。can’t说明不允许，must说明必须。有效规则指向具体行为和场所，而不是只写“Be good”。'),
S('正例1：走廊里的安全规则','Walk in the hallway. Don’t run! 走廊空间狭窄、转角有遮挡，奔跑会增加碰撞风险。第一句给出替代行为，第二句明确禁止危险行为。',['Walk in the hallway. Don’t run.','Walking in hallway. No running you.','You must to walk and don’t running.'],0,'正确：两个祈使句都使用动词原形，行为清楚。','祈使句省略主语you；Don’t后必须接动词原形。'),
S('正例2：图书馆和教室的规则不同','We must keep quiet in the library, but we can ask questions in class at the right time. 规则取决于场所功能；quiet并不表示任何地方都不能说话。',['We must keep quiet in the library.','We must keep quiet in the playground at all times.','We can shout in the library because it is public.'],0,'正确：安静规则与阅读场景一致。','不能脱离地点套用同一规则；先判断空间用途。'),
S('反例与易错点：规则形式不能互相混写','“Don’t to run”多了to；“We must to keep quiet”也错；“No eat”应写Don’t eat或No eating。can’t表示不允许，不等于没有能力，例如We can’t eat in class通常是规则。',['Don’t eat in class. / No eating in class.','Don’t to eat in class.','We mustn’t to eating in class.'],0,'正确：Don’t + 原形；No + 动名词是标志常见形式。','先判断使用句子还是标志短语，再保持结构完整。'),
S('教材型练习：把四个标志配到校园地图','标志依次表示：走廊慢走、图书馆安静、教室不吃东西、餐厅排队。先找地点功能，再判断规则是肯定指令还是否定禁令，最后选择能与地点和行为一一对应的一组规则。',['Walk in the hallway; keep quiet in the library; don’t eat in class; wait in line in the dining hall.','Run in the hallway; shout in the library; eat in class; push in the dining hall.','四个地点都只写Be good。'],0,'正确：每条规则都包含可观察行为，并与地点功能对应。','标志不是装饰；逐一核对地点、行为和正负方向。'),
S('解释理由：为什么禁止后还要给替代行为？','只说Don’t run告诉学生不能做什么，却没有说明下一步。补上Walk slowly把禁止转化为可执行选择，更容易遵守。设计规则时同时写风险和替代行为。'),
S('跨学科迁移：用速度和反应距离验证走廊规则','在安全模拟中比较步行1米/秒和奔跑3米/秒，按相同反应时间0.7秒计算反应距离；把结果写进双语安全标志，解释为什么转角前必须减速。'),
S('掌握检测与小结','为实验室门口设计一块规则牌：至少含一个肯定祈使句、一个Don’t句、一个must句，并分别写明目标行为、危险来源和可执行替代方案。',['Wear safety glasses. Don’t touch wires with wet hands. You must follow the teacher’s instructions.','To wear glasses. Don’t touching wires. You must to follow.','Be good. No danger. Careful.'],0,'通过：三种规则结构正确，并能追溯到具体风险。','尚未通过：先修复原形结构，再补齐地点、风险与替代行为。')
],{subject:'物理与数学',title:'英语 × 安全工程：走廊减速规则的数据证据',copy:'设反应时间0.7秒，比较步行1米/秒和奔跑3米/秒时反应阶段经过的距离；用结果设计“Don’t run / Walk slowly”双语标志。',labels:['读取速度与反应时间','计算两种反应距离','把数据写入规则及理由'],options:['计算0.7米与2.1米，再用英语说明减速能缩短反应距离','只写Don’t run，不处理数据','在真实走廊组织奔跑碰撞实验'],success:'完成：速度×反应时间给出0.7米与2.1米，物理风险解释规则，英语标志给出禁止和替代行为。'}),
'eng7b:1:1':L('规则如何帮助我们：从Alice与Dr Know文本提取问题、感受和建议','能从家规与校规文本中区分事实、感受和原因；能按“规则—目的—影响—建议”整理Alice的问题并写给Eric一封有同理心、可执行的建议信。',{kind:'rule-impact-map',label:'切换Alice的生活片段，连接规则、可能目的、感受和可协商方案'},[
S('概念讲授：理解规则不等于盲目接受或全部反对','阅读规则求助信要分四栏：具体规则、当事人感受、规则可能保护的目标、可以讨论的调整。Dr Know先承认Alice感到不自由，再解释规则帮助形成秩序，并建议她与家人沟通。'),
S('正例1：早起与整理房间的规则','Alice has to get up early and make her bed. 她觉得规则很多；家长可能希望她按时到校并管理个人空间。合理建议是共同制定早晨时间表，而不是断言家长“不喜欢她”。',['Make a morning plan and discuss which tasks are necessary.','Break every rule without talking.','Say her parents are bad without evidence.'],0,'正确：建议回应感受，也处理时间与责任。','不要把感受直接当成他人动机；提出可协商步骤。'),
S('正例2：完成作业后才能放松','She must do her homework before she can relax. 先完成责任再娱乐可能保护学习时间，但若作业量过大，也可以记录用时并与老师、家长讨论。',['Record homework time and discuss a realistic break plan.','Hide the homework and say it is finished.','Use can to mean there is no rule.'],0,'正确：先获取时间证据，再提出可执行调整。','建议不能靠欺骗；can与must表达的约束不同。'),
S('反例与易错点：建议不能只重复规则','“Follow the rules because rules are rules”没有解释目的，也没有回应压力；“Ignore all rules”同样跳过安全和共同利益。好建议应指出哪条规则、影响谁、可改变什么。',['先确认规则目的，再提出具体沟通时间和方案','把所有规则都说成绝对正确','只告诉Alice不要难过'],0,'正确：建议包含理解、依据和下一步。','同理心不是空泛安慰；必须连接具体问题。'),
S('教材型练习：完成Alice—Dr Know阅读表','从文本中为三条规则分别填写：rule、feeling、possible purpose、advice；再选一句最适合作为回信开头的话。',['I understand that so many rules can feel difficult. Let’s look at what each rule is for.','You are wrong. Rules are always perfect.','Dear Alice, just do everything.'],0,'正确：先回应感受，再进入规则分析。','回信开头要建立信任，不能先指责或敷衍。'),
S('解释理由：为什么同一条规则可能需要复审？','规则的目标可能合理，但执行方式、时间或范围仍可能过度。用实际记录检查它是否有效、是否公平、是否产生额外负担，再决定保留、修改或增加例外。'),
S('跨学科迁移：把规则效果做成一周数据表','选择一条家庭规则，连续7天记录执行时间、完成率、冲突次数和感受评分；比较调整前后数据，用英语写“数据发现—限制—建议”，不能只凭一天体验下结论。'),
S('掌握检测与小结','Eric抱怨晚上必须九点前收起手机。选一封既说明睡眠目的、承认沟通需求，又给出一周试行与复盘方法的建议；完成后检查建议是否包含感受、规则目的、具体行动和评价证据四部分。',['I understand the rule feels strict. Try a one-week plan, record sleep and homework, then discuss the results with your family.','Rules are rules. Stop complaining.','Hide the phone and use it after everyone sleeps.'],0,'通过：建议兼顾目的、感受、数据和协商步骤。','尚未通过：回信不能只有命令，要有证据和复盘机制。')
],{subject:'数学与社会实践',title:'英语 × 数据记录：一周规则效果评估',copy:'选一条家庭或班级规则，连续7天记录执行情况、耗时、冲突次数和感受评分；比较数据，用英语向相关人员提出保留或调整建议。',labels:['定义可记录指标','连续七天记录并比较','写英语结论、限制和建议'],options:['保留每日原始数据，用一周结果支持具体调整建议','只记录最糟的一天代表整周','先决定结论再补数字'],success:'完成：时间序列减少单日偏差，英语回信区分事实、感受和建议，并给出下一轮复盘。'}),
'eng7b:1:2':L('祈使句与can、have to、must：区分指令、许可、外部要求和强制义务','能正确构造肯定/否定祈使句；能区分can/can’t的许可、have to/don’t have to的外部要求与非必要、must/mustn’t的强义务与禁止，并在口语中突出规则关键词。',{kind:'modal-rule-lab',label:'改变规则来源和强度，观察imperative、can、have to、must怎样表达不同约束'},[
S('概念讲授：先判断规则功能，再选择句型','直接指令用动词原形：Close the door。禁止指令用Don’t。can/can’t表示允许或不允许；have to多指外部安排；must强调说话人认为必要；mustn’t表示禁止，而don’t have to表示“不必”，两者相反。'),
S('正例1：许可和能力要看语境','Students can use the library after school在规则表中表示允许；Mia can swim表示能力。We can’t eat in class表示不允许，并不等于学生没有吃东西的能力。',['You can read here, but you can’t bring food.','You can’t eat means you are physically unable to eat.','Can is always about talent.'],0,'正确：同一个情态动词由语境决定是许可还是能力。','先看句子是在规则表还是能力介绍中。'),
S('正例2：have to与must的来源不同','We have to wear the school uniform说明学校的外部规定；I must remember my project强调说话人的强烈责任。两者后面都接动词原形。',['We have to wear uniforms. / I must finish the safety check.','We have wear uniforms. / I must to finish.','We has to wearing uniforms.'],0,'正确：have to和must都接动词原形，主语变化影响have/has。','have to不是一个不可变化的整体；he/she用has to。'),
S('反例与易错点：mustn’t不等于don’t have to','You mustn’t enter表示严禁进入；You don’t have to enter表示不必进入，但可以选择进入。把两者互换会把“可选”变成“禁止”，在安全规则里后果严重。',['You mustn’t touch the hot plate. = 禁止触碰','You don’t have to wear a coat. = 禁止穿外套','You mustn’t come early. = 不必早来'],0,'正确：mustn’t是禁止；don’t have to是不必要。','先判断行为是否被允许，再翻译否定结构。'),
S('教材型练习：完成Grammar Focus规则表','填空：___ quiet in the library. / Students ___ eat in class. / We ___ arrive before 8:00 because school starts then. / You ___ bring extra paper; the teacher provides it.',['Keep; can’t; have to; don’t have to','Keeping; must to; can’t; mustn’t','To keep; don’t can; has to; can’t'],0,'正确：指令、禁止、外部时间要求和非必要分别匹配。','最后一句是“不必携带”，不是“禁止携带”。'),
S('解释理由：为什么情态强度必须准确？','规则语言会改变权利和义务。can给予许可，can’t和mustn’t限制行为，have to指出外部要求，don’t have to保留选择。表达错误可能让安全规则或公平边界发生反转。'),
S('跨学科迁移：为物理实验建立分级安全规则','观察电路实验的风险，把事项分成“允许”“建议”“必须”“严禁”四级；用can、should、must/have to、mustn’t写双语卡，并让同伴根据句子恢复风险等级。'),
S('掌握检测与小结','实验即将开始：电源关闭时可连接电路；通电前必须检查；严禁湿手触线；护目镜已统一提供所以不必自带。选择四句含义准确的规则。',['You can connect the circuit with the power off. You must check it before switching on. You mustn’t touch wires with wet hands. You don’t have to bring goggles.','You mustn’t connect anything. You don’t have to check. You can touch wet wires. You mustn’t bring goggles.','You can to connect. You must checking. You don’t have to touch wet wires.'],0,'通过：许可、义务、禁止和非必要四级清楚且结构正确。','尚未通过：重点重学mustn’t与don’t have to的意义边界。')
],{subject:'物理实验安全',title:'英语 × 风险分级：给电路实验写四级规则',copy:'识别断电接线、通电前检查、湿手触线和护目镜四种情境，按允许、必须、严禁、非必要分级，再用can、must、mustn’t、don’t have to表达。',labels:['识别行为与危险后果','确定许可或义务等级','用准确情态动词写双语规则'],options:['按风险分级后分别使用can、must、mustn’t、don’t have to','所有句子都用must，忽略含义差别','把mustn’t和don’t have to当成同义词'],success:'完成：物理风险决定规则等级，英语情态动词准确编码许可、义务、禁止和非必要。'}),
'eng7b:2:0':L('运动与锻炼频率：用How often调查并准确报告一周活动','能听懂并询问do sport、exercise、go running、play basketball等活动频率；能用every day、once/twice a week和频度副词把活动、次数、周期与真实记录对应。',{kind:'fitness-frequency-lab',label:'切换一周运动记录，观察次数、周期、How often问答与频度副词怎样对应'},[
S('概念讲授：频率回答必须同时说明次数和周期','How often询问某事在一段时间内发生多频繁。once a week是一周一次，twice a week是一周两次，three times a week是一周三次；every day通常是一周七次。不要把How often与询问时长的How long混淆。'),
S('正例1：从周记录回答How often','Mia在周一、周三和周六跑步，因此问How often does Mia go running? 可答She goes running three times a week。次数来自三天记录，does后的go用原形，答句goes随主语变化。',['She goes running three times a week.','She go running three time a week.','She goes running for three hours a week.'],0,'正确：活动、三次和一周周期完整对应。','检查How often问频率，不要把三次换成三小时。'),
S('正例2：频度副词表达大致规律','Leo六天步行上学，可说He usually walks to school；只在一天骑车，可说He sometimes rides a bike。always、usually、often、sometimes、hardly ever、never表达由高到低的大致频率。',['He usually walks to school and sometimes rides a bike.','He never walks because he walks six days.','He usually is walk to school.'],0,'正确：副词与周数据一致，并放在实义动词前。','频度副词是概括，不可与原始记录明显矛盾。'),
S('反例与易错点：次数、时长和频率不能互换','“I exercise two hours”回答的是时长且缺少for；“I exercise twice”没有周期；“How many do you exercise?”结构错误。频率应写twice a week，时长才写for two hours。',['I exercise twice a week, for about forty minutes each time.','I exercise two hours week.','How many often do you exercise?'],0,'正确：频率与单次时长被分别表达。','先判断题目问How often还是How long，再选次数或时长。'),
S('教材型练习：根据活动表完成采访','活动表显示：篮球周二和周五，游泳周日，拉伸每天。先逐项数出七日记录中的次数，再选择能完整复述三项频率的答案，并向同伴追问最常做哪项运动及每次持续多久。',['I play basketball twice a week, swim once a week, and stretch every day.','I play basketball two week and swim one time day.','I always swim because Sunday is one day.'],0,'正确：三项活动都由日历记录支持。','逐项数日期，再写once、twice或every day。'),
S('解释理由：为什么频率调查要先规定时间范围？','“often”对不同人可能含义不同；规定“过去七天”并记录实际次数，才能比较。问卷应统一活动定义、观察周期和计数方法，否则同样的回答可能代表不同运动量。'),
S('跨学科迁移：制作班级一周运动频率图','调查5名同学过去7天的运动天数，把0—7天画成条形图；计算平均运动天数，再用英语写最高、最低和平均频率。数学负责统计，英语负责把数据转成可核查结论。'),
S('掌握检测与小结','一张周表显示Ben周一、周四踢足球，周二、周三、周五散步，周末休息。选出正确的How often问答，并说明often只是概括，twice a week才是精确频率。',['How often does Ben play football? He plays twice a week. He often walks on school days.','How long Ben plays football? He play two times.','How many football does Ben often? He plays for twice.'],0,'通过：问句、精确频率和概括性副词均与记录一致。','尚未通过：重新区分次数、周期、时长和频度副词。')
],{subject:'数学与健康数据',title:'英语 × 统计：班级七日运动频率报告',copy:'统一调查“过去7天”，记录5名同学的运动天数，绘制0—7天条形图并计算平均值；用英语报告最高、最低和平均频率。',labels:['统一活动定义与七日周期','记录数据并计算平均值','用How often语言报告图表'],options:['保留个人原始记录，算平均值后用准确频率表达','只问大家觉得自己是否经常运动','把运动时长直接当成运动次数'],success:'完成：统一周期使数据可比较，统计图展示次数差异，英语准确区分精确频率与概括副词。'}),
'eng7b:2:1':L('运动如何帮助我们：从阅读证据连接身体、情绪与行动建议','能从健康文本提取运动类型、身体或情绪变化及证据；能用be good for、help、make、because解释运动益处，同时避免把相关性夸大成万能因果。',{kind:'fitness-benefit-map',label:'切换运动案例，连接活动强度、身体反应、情绪变化、证据与安全建议'},[
S('概念讲授：运动益处要写清“活动—变化—证据”','“Exercise is good for us”只是总观点。完整说明要指出哪种活动、影响哪个方面、有什么观察或研究证据。例如 brisk walking raises the heart rate and can improve endurance when done regularly。'),
S('正例1：有氧运动与心肺耐力','快走时呼吸和心率适度加快，长期规律练习可提高耐力。可说Brisk walking is good for the heart and lungs because it makes them work harder safely。一次走路后的疲劳不能直接证明长期效果。',['Regular brisk walking can improve endurance over time.','One walk proves everyone will never be tired.','Walking makes the heart stop working hard.'],0,'正确：结论限定为规律运动和长期变化。','健康结论要注明条件，不能用一次体验推出永久结果。'),
S('正例2：运动与情绪和睡眠','After cycling for thirty minutes, Ana reports feeling calmer and falls asleep earlier。运动可能帮助调节情绪和睡眠，但还要记录作息、咖啡因等变量，不能把所有变化都归因于骑车。',['Cycling may help Ana relax; track other factors too.','Cycling certainly cures every sleep problem.','Because Ana sleeps, cycling is the only cause.'],0,'正确：使用may并主动检查其他变量。','个人观察可提出假设，不能直接证明唯一因果。'),
S('反例与易错点：运动不是越多越好','“Exercise all day without rest”忽略恢复、补水和受伤风险；疼痛时继续高强度训练也不安全。合适计划应包含热身、逐步增加强度、休息和停止信号。',['Increase activity gradually and stop if there is sharp pain.','Train through every pain to get fit faster.','Never rest because rest is unhealthy.'],0,'正确：建议同时考虑收益、强度和安全边界。','区分正常用力感与尖锐疼痛，运动建议不能脱离个体状况。'),
S('教材型练习：完成运动益处证据表','阅读三段材料，把swimming、walking和team sports分别连接到全身肌肉、日常耐力、合作与情绪支持；再选择没有过度推断的一项结论。',['Different activities support different parts of fitness; regular practice matters.','Every sport produces exactly the same result.','Team sports guarantee that nobody feels sad.'],0,'正确：结论保留运动类型差异和规律性条件。','不要把“可能帮助”改成“保证”，也不要抹去不同活动作用。'),
S('解释理由：为什么健康建议必须包含剂量和边界？','活动类型、频率、强度和时间共同决定训练量；相同运动对不同基础的人反应不同。只有写清这些条件，建议才可执行、可比较，也能减少受伤和过度训练风险。'),
S('跨学科迁移：测量运动前后心率并解释','静坐后测15秒脉搏并乘4得到每分钟心率；原地踏步2分钟后再次测量，休息3分钟再测。用折线记录三次数据，并用英语描述上升和恢复，不作疾病诊断。'),
S('掌握检测与小结','学生运动前心率76，踏步后124，休息三分钟后88。选择既准确描述数据、又包含安全边界的总结，并指出还需多次测量才能判断规律。',['The heart rate rose during exercise and moved toward the resting level after recovery; repeat the test under the same conditions.','Exercise always makes every heart healthy because 124 is high.','A heart rate of 88 proves the student is ill.'],0,'通过：描述变化、恢复和重复测量需求，没有越界诊断。','尚未通过：数据支持趋势描述，不支持万能疗效或医学诊断。')
],{subject:'生物与数学',title:'英语 × 生理测量：运动前后心率恢复实验',copy:'在安全、低强度活动中测量静息、运动后和恢复后的每分钟心率，绘制三点折线；用英语描述变化与限制，不作医学诊断。',labels:['统一测量方法并取静息值','完成活动并记录三次心率','用英语解释上升、恢复与限制'],options:['按15秒脉搏×4统一计算并比较三次数据','只测运动后一次就判断健康水平','进行超高强度运动以制造最大差异'],success:'完成：生理测量提供心率数据，数学图表显示变化与恢复，英语用限定语作出不过度的解释。'}),
'eng7b:2:2':L('物主代词与频度副词：准确表达所属关系和习惯频率','能区分my/mine、your/yours、his、her/hers、our/ours、their/theirs；能把always、usually、often、sometimes、hardly ever、never放在be动词后、实义动词前，并用真实数据校验语义。',{kind:'fitness-grammar-lab',label:'切换人物、物品与运动频率，观察形容词性/名词性物主代词及副词位置'},[
S('概念讲授：物主代词看后面有没有名词，频度副词看谓语类型','形容词性物主代词后接名词：my racket；名词性物主代词独立替代“物主代词+名词”：The racket is mine。频度副词通常放实义动词前，却放在be后：I often run；I am often tired。'),
S('正例1：my与mine不能占同一位置','This is my basketball. The blue basketball is mine。第一句my修饰basketball，第二句mine已包含“my basketball”，后面不能再接名词。',['This is her bike. That bike is hers.','This is hers bike. That bike is her.','This is she bike. That bike is she’s.'],0,'正确：her修饰名词，hers独立作表语。','先遮住名词：后面有名词用her，没有名词并表示所属用hers。'),
S('正例2：频度副词的位置由动词决定','They usually exercise after school；They are usually active in PE class。exercise是实义动词，usually放前面；are是be动词，usually放后面。',['He often plays tennis, and he is often energetic.','He plays often tennis, and he often is energetic.','He is play often tennis.'],0,'正确：实义动词前、be动词后的位置都正确。','不要机械固定在句首；先找谓语中心。'),
S('反例与易错点：never本身已是否定，mine不能再接名词','“I don’t never swim”形成双重否定；标准表达是I never swim。“Mine shoes”错误，应为my shoes或The shoes are mine。his既可修饰名词也可独立使用，是特殊形式。',['I never use his racket; mine is lighter.','I don’t never use him racket; my is lighter.','Mine racket is light and her is heavy.'],0,'正确：never不再搭配don’t，his和mine位置正确。','逐句检查否定是否重复，以及代词后是否错误接名词。'),
S('教材型练习：归还运动装备并描述习惯','失物台有Lily的球拍、Tom的球和我们的跳绳。先根据标签判断每件装备属于谁，再选择一组既正确说明归属、避免重复名词，又正确加入运动频率和副词位置的句子。',['The racket is hers. The ball is his. The skipping rope is ours. We often use it after school.','The racket is her. The ball is him. The rope is our. We use often it.','Hers racket, his ball and ours rope are here.'],0,'正确：名词性物主代词独立使用，often位于实义动词前。','先完成“谁的”，再定位谓语决定副词位置。'),
S('解释理由：为什么名词性物主代词能避免重复？','比较This is my racket and that is your racket，与This is mine and that is yours。第二种在所指清楚时省去重复名词，使对话自然；但第一次出现或所指不清时仍需说出名词。'),
S('跨学科迁移：用运动装备建立归属和频率数据库','为小组装备记录owner、item、weekly uses三列；根据所有者生成my/your/his/hers/ours/theirs句子，根据每周次数生成never到always的频率描述，并检查描述是否与数字相符。'),
S('掌握检测与小结','数据表显示篮球属于Lily且她每周使用5天，跳绳属于我们且每周使用2天。选择同时正确表达所属、代词替代和频度位置的一组句子。',['The basketball is hers, and she often uses it. The skipping rope is ours, and we sometimes use it.','The basketball is her, and she uses often it. Our is the rope, and we never sometimes use it.','Hers basketball is often use. The rope is our.'],0,'通过：所属形式、副词位置和数字对应关系均正确。','尚未通过：分别检查代词是否接名词、副词位于何种谓语旁。')
],{subject:'信息技术与数学',title:'英语 × 数据表：装备归属与使用频率核验',copy:'建立owner、item、weekly uses三列表格；把所有者转换为两类物主代词，把0—7次转换为频率表达，并逐项核对英语描述是否忠实于数据。',labels:['登记装备、所有者和周次数','生成物主代词与频率句','用原始数据核验每条描述'],options:['保留三列原始数据，再分别生成所属和频率表达','只看物品颜色猜所有者和频率','把mine、my和always随机互换'],success:'完成：数据表确定真实归属和使用次数，英语用两类物主代词避免歧义，并用频度副词概括数值规律。'}),
'eng7b:3:0':L('食物喜好与点餐：用like、would like和菜单信息作出完整选择','能识别常见主食、蔬菜、水果、饮料与菜品；能用What would you like?、I’d like…、Would you like…?完成礼貌点餐，并说明喜好与本次选择的区别。',{kind:'food-choice-lab',label:'切换人物需求、菜单和份量，观察喜好、点餐表达、价格与完整订单怎样对应'},[
S('概念讲授：长期喜好和当下点餐使用不同表达','I like noodles表示一般喜好；I’d like noodles表示现在想点面条。服务员可问What would you like?或Would you like some soup? 回答应包含菜品、份量和必要限制，而不只是说Yes。'),
S('正例1：从菜单组成完整订单','菜单有beef noodles 18元、vegetable soup 8元。顾客现在想吃面且不吃牛肉，可以说I’d like tomato noodles, please。若菜单没有该项，应先询问Do you have tomato noodles?',['I’d like tomato noodles, please. Do you have them?','I like tomato noodles yesterday, give me.','I would liking beef but no beef.'],0,'正确：使用礼貌点餐结构，并先核对菜单供应。','would like后接名词或to do，不使用liking；限制条件要说清。'),
S('正例2：Would you like的回答要补全信息','Would you like some orange juice? — Yes, please. A small glass。若不需要可答No, thanks. I’d like water。礼貌回应之后补充份量或替代品，订单才可执行。',['No, thanks. I’d like a bottle of water.','No, I don’t like all drinks forever.','Yes, I would orange juice two.'],0,'正确：拒绝、替代品和量词都清楚。','拒绝本次饮料不等于永久不喜欢；量词应与饮料搭配。'),
S('反例与易错点：like与would like不能混成同一时态','“I would like eat rice”缺少to；“I am like dumplings”把like误作进行时；“Would you like?”若没有上下文会缺少对象。正确形式是would like + 名词，或would like to + 动词。',['I would like some rice. / I would like to order rice.','I would like eat rice.','I am liking dumplings every day.'],0,'正确：名词结构和不定式结构均完整。','先看like后面接食物还是动作，再决定是否需要to。'),
S('教材型练习：完成三人午餐订单','菜单显示鸡肉饭15元、蔬菜面12元、汤6元。Amy不吃肉，Ben想要米饭，Cindy只要汤；选择能够逐人匹配需求、菜品和价格的一组订单。',['Amy: vegetable noodles ¥12; Ben: chicken rice ¥15; Cindy: soup ¥6. Total: ¥33.','Amy: chicken rice; Ben: soup; Cindy: noodles. Total ¥12.','Three food, thirty-three yuans, no names.'],0,'正确：三个人的限制、菜品、小计和总价均一一对应。','逐人核对需求再相加；人民币yuan通常不加复数-s。'),
S('解释理由：为什么点餐必须复述确认？','嘈杂环境中菜名、数量和限制容易听错。服务员复述“One vegetable noodle, one chicken rice and one soup—is that right?”让顾客在制作前纠错，也训练听取关键信息。'),
S('跨学科迁移：在预算内设计三人午餐','使用菜单价格和三人的饮食限制，在45元预算内组合一份午餐；列出每项小计、总价和找零，并用英语完成点餐与服务员复述。'),
S('掌握检测与小结','顾客有30元、不吃花生，菜单中面条16元、花生甜点10元、果汁8元。选出安全且不超预算的订单，使用would like并主动确认过敏原。',['I’d like the noodles and juice, please. Do the noodles contain peanuts? The total is ¥24.','I’d like the peanut dessert because it is cheap.','I like all food. Give me thirty yuan.'],0,'通过：点餐、限制、价格计算和确认问题完整。','尚未通过：本次选择必须同时满足安全限制、菜单和预算。')
],{subject:'数学与生活规划',title:'英语 × 预算：45元三人午餐点餐任务',copy:'读取菜单单价与三人的饮食限制，在45元内选择菜品；计算每项小计、总价与找零，并用英语完成点餐、数量确认和服务员复述。',labels:['匹配三人需求与菜单','计算小计、总价和找零','完成英语点餐与复述确认'],options:['先满足限制，再计算总价并用完整订单复述','只选最便宜菜，不管谁能吃','直接说food，不核对菜名和数量'],success:'完成：需求决定菜品，数学验证预算，英语把菜名、数量、限制和确认组成可执行订单。'}),
'eng7b:3:1':L('健康饮食选择：从食物成分、份量和饮食记录形成有证据的建议','能从短文和食品信息中提取食物种类、主要营养、糖盐含量与份量；能用should、need、too much和because提出具体、可执行且不过度的健康建议。',{kind:'nutrition-evidence',label:'切换早餐、饮料和零食信息，连接成分、份量、身体需要与替代选择'},[
S('概念讲授：健康选择看整体搭配，不给单一食物贴好坏标签','一餐可从主食、蛋白质来源、蔬果和饮品检查多样性，也要看份量和频率。水果有营养，但果汁和整果在纤维、糖摄入速度上不同；“healthy”不是无限量食用的许可。'),
S('正例1：用具体替代方案改进早餐','只有甜饮料和饼干的早餐缺少持续能量与多样性。建议可写Add an egg and a piece of fruit, and replace the sugary drink with water。行动明确，比“Eat healthily”更可执行。',['Add an egg and fruit; choose water instead of the sugary drink.','Never eat breakfast because biscuits have sugar.','Drink three sweet drinks for more energy.'],0,'正确：建议补充食物种类并提供可操作替代。','不要从一项不足跳到极端禁食；说明增加什么、替换什么。'),
S('正例2：阅读标签时必须按实际份量换算','饮料标签写每100毫升含糖8克，一瓶250毫升，则整瓶含糖8×2.5=20克。不能只看到“8克”就当作整瓶，也不能忽略实际喝了多少。',['A 250 ml bottle contains 20 g of sugar.','The whole bottle contains 8 g because the label says 100 ml.','Sugar is 8×250 grams.'],0,'正确：先求250/100，再乘每100毫升含量。','单位换算后再计算，避免把毫升直接当倍数。'),
S('反例与易错点：一顿饭不能代表长期饮食','看到一次炸物就说“你饮食一定不健康”是过度推断；一天只吃沙拉也未必均衡。合理评价需要多日记录、实际份量和个人需求，建议不能替代医生诊疗。',['Record several days and look for repeated patterns.','One meal proves a person is unhealthy forever.','Everyone must eat exactly the same amount.'],0,'正确：使用多日证据并保留个体差异。','区分一次选择与长期模式，不作医学诊断。'),
S('教材型练习：比较两份午餐并提出改进','A餐为米饭、鱼、青菜和水；B餐为薯条、炸鸡和大杯甜饮。选择最严谨比较：指出A餐种类更丰富，同时说明仍需看份量与整日饮食。',['Meal A offers more food groups, but portions and the whole-day record still matter.','Meal A is perfect and can be eaten without limits.','Meal B is poison and must never be eaten.'],0,'正确：比较基于食物组合，又保留份量和长期记录条件。','健康表达避免perfect、poison等绝对化标签。'),
S('解释理由：为什么“少吃”必须转化为可测量行动？','“少糖少盐”方向正确但难执行。把它改成“本周三天用水替代甜饮，并记录饮料容量”，就能观察完成率和摄入变化；目标必须具体、可记录、可复盘。'),
S('跨学科迁移：换算整瓶含糖量并改进饮料选择','读取每100毫升含糖量和瓶装容量，计算整瓶糖量；比较水、无糖饮料与甜饮的使用情境，设计一周替代计划并用英语说明数据依据与限制。'),
S('掌握检测与小结','标签显示每100毫升含糖6克，一瓶300毫升。学生每天喝一瓶；选出正确计算、谨慎结论和可执行替代方案，并说明个人健康问题应咨询专业人员。',['The bottle contains 18 g of sugar. Try water on three days this week and record the change.','It contains 6 g, so drinking any number is fine.','It contains 1,800 g and proves the student is ill.'],0,'通过：换算、限定结论和行动计划完整且不越界诊断。','尚未通过：先统一容量单位，再把建议写成可记录行动。')
],{subject:'数学与生物',title:'英语 × 营养标签：整瓶含糖量换算与替代计划',copy:'读取每100毫升含糖克数和饮料容量，计算整瓶含糖量；比较一周饮用记录，制定三天替代计划，并用英语说明计算、选择和限制。',labels:['读取每100毫升数据与容量','换算整瓶含糖量并比较','写英语替代计划与证据限制'],options:['统一单位、按容量倍数计算，再设计可记录替代计划','把每100毫升数字直接当整瓶数据','仅凭一次饮用诊断疾病'],success:'完成：数学换算揭示实际摄入，生物知识说明身体需求，英语把证据转成具体但不过度的建议。'}),
'eng7b:3:2':L('可数与不可数名词：用数量词准确描述食物和购物需求','能区分apple等可数名词与rice、milk等不可数名词；能正确使用a/an、some/any、many/much、a few/a little以及容器量词，并在肯定句、疑问句和否定句中保持一致。',{kind:'noun-quantity-lab',label:'改变食物类型、句式和包装，观察单复数、some/any、many/much及容器量词怎样变化'},[
S('概念讲授：先判断能否直接逐个计数，再选择数量表达','apple可逐个计数：an apple、three apples、many apples；rice通常作为物质不可直接数：some rice、much rice。需要精确数量时使用a bowl of rice、two bottles of milk等容器或单位。'),
S('正例1：some与any随句式和交际目的变化','肯定陈述We have some eggs；一般疑问Do we have any milk?；否定We don’t have any milk。提出或请求且期待肯定回应时常用some：Would you like some tea?',['We have some eggs, but we don’t have any milk.','We have any eggs and no some milk.','Do we have some milks?'],0,'正确：肯定句some、否定句any，milk保持不可数。','先判断句式与交际功能，再判断名词是否复数。'),
S('正例2：many和much取决于名词类型','How many tomatoes do we need? — Six。How much cheese do we need? — Two hundred grams。tomatoes可数用many，cheese不可数用much并借助克数精确表达。',['How many tomatoes? How much cheese?','How much tomatoes? How many cheese?','How many tomato? How much cheeses?'],0,'正确：问词与名词类型匹配，答案提供数量或单位。','不可数不等于无法测量，而是需借助质量、体积或容器单位。'),
S('反例与易错点：容器复数变化，内容物形式通常不变','two bottle of milks错误；应写two bottles of milk。a few用于可数复数，a little用于不可数；few/little往往带“几乎没有”的消极含义，不能随意互换。',['two bottles of milk; a few apples; a little rice','two bottle of milks; a little apples','many rice; much oranges'],0,'正确：容器承担复数，内容物按不可数形式保留。','先数容器还是内容物，再选择复数位置和数量词。'),
S('教材型练习：根据厨房库存写购物清单','库存有2个鸡蛋、少量米饭、没有牛奶、只有1个番茄。选择能准确使用some/any、a little/a few和容器量词的购物清单说明。',['We have a few eggs and a little rice, but we don’t have any milk. We need a carton of milk and some tomatoes.','We have a little eggs and a few rice. We need milks.','We don’t have some milk and need much tomato.'],0,'正确：库存、缺货和采购数量均符合名词类型。','把每个名词标成C或U，再选择限定词与包装单位。'),
S('解释理由：为什么不可数名词仍然可以精确测量？','“不可数”只表示不能直接用one, two逐个数这个名词，不表示没有数量。rice可按克、碗或袋测量，water可按毫升、杯或瓶测量；测量单位使购物和烹饪可执行。'),
S('跨学科迁移：按食谱比例调整四人份食材','食谱两人份需要200克米、2个鸡蛋和300毫升水。把它扩大为四人份，分别用grams、eggs和millilitres表达，并写出How many/How much采购问句。'),
S('掌握检测与小结','两人份粥需要100克米、500毫升水和1个苹果；现在做六人份。选择正确放大结果及英语表达，并解释rice/water为何用much、apple为何用many。',['We need 300 grams of rice, 1,500 ml of water and three apples. How much rice and how many apples do we need?','We need three rices, three waters and much apples.','We need 600 grams rice because six people means ×6.'],0,'通过：比例按人数×3，单位、复数和问词全部正确。','尚未通过：先算份数倍数，再分别处理可数名词与测量单位。')
],{subject:'数学与劳动实践',title:'英语 × 比例：把两人份食谱调整为四人份',copy:'读取两人份食谱中的克数、毫升数和食材个数，按人数比例扩大为四人份；用How much/How many写采购问题并生成可执行清单。',labels:['区分可数食材与测量单位','按人数比例计算四人份','用英语数量结构生成清单'],options:['先求人数倍数，再分别换算克、毫升和个数','所有食材一律在单词后加-s','人数加2，所有食材也只加2'],success:'完成：比例计算决定实际采购量，测量单位处理不可数食材，英语准确区分many、much与容器量词。'}),
'eng7b:4:0':L('此刻正在做什么：从现场线索听懂、询问并报告正在进行的活动','能识别read、cook、exercise、wait、take photos等现场活动；能用What are you doing?、I am…和What is he/she doing?、He/She is…完成电话或视频通话，并以可观察线索支持判断。',{kind:'live-action-monitor',label:'切换直播画面和时间点，观察人物、动作线索、be动词与-ing形式怎样同步变化'},[
S('概念讲授：现在进行时拍摄“说话这一刻”的动作','现在进行时由am/is/are + 动词-ing构成。I am reading表示我现在正在读；She is cooking表示她此刻正在做饭。先找主语，再选be动词，最后把动作变成-ing形式，三个部件缺一不可。'),
S('正例1：电话中用问答确认对方此刻的动作','—What are you doing right now? —I’m waiting for the bus. 回答不是猜测习惯，而是报告电话发生时的现场状态；right now与背景里的车站广播共同提供时间证据。',['I’m waiting for the bus right now.','I waiting for the bus right now.','I wait for the bus right now every Sunday.'],0,'正确：I搭配am，wait变为waiting，句子明确指向此刻。','检查主语后的be动词和动作词的-ing形式。'),
S('正例2：从声音和画面报告第三人称活动','画面中爸爸系着围裙、锅正在冒热气，可问What is Dad doing? 回答He is cooking dinner. 妹妹手里拿着相机，可说She is taking photos. 代词变化时be动词也要随之变化。',['Dad is cooking, and my sister is taking photos.','Dad are cook, and my sister taking photos.','Dad cooks now, and my sister is take photos.'],0,'正确：两个现场动作都使用is + 动词-ing。','不要只看到动词；主语、be动词和-ing要整体检查。'),
S('反例与易错点：不能遗漏be动词，也不能把状态动词机械加-ing','He playing chess缺少is；I am knowing the answer通常不自然，应说I know the answer。现在进行时适合可展开的临时动作，不是所有带now的句子都必须使用-ing。',['He is playing chess now, but I know the answer.','He playing chess now, and I am knowing the answer.','He is play chess now, but I knowing the answer.'],0,'正确：动作使用is playing，状态know使用一般现在时。','先判断是不是正在展开的动作，再决定能否使用进行时。'),
S('教材型练习：根据公园现场图完成电话报告','公园里两名学生在打羽毛球，一位老人正在遛狗，记者正在拍照。选择同时回答“谁、在哪里、正在做什么”的完整报告，并检查每个主语对应的be动词。',['Two students are playing badminton in the park. An old man is walking his dog, and a reporter is taking photos.','Two students play badminton yesterday. An old man walking a dog.','There are people in the park, and they are nice.'],0,'正确：人物、地点和三个正在发生的动作都与现场图对应。','报告现场要给出可核对的动作，而不是只写模糊评价。'),
S('解释理由：为什么现场报告必须依靠时间与观察证据？','同一个人可能每天跑步，但此刻正在休息；习惯和当前动作不能混为一谈。听到背景声、看到姿势、读取“10:15 LIVE”时间戳，才能把动词形式与真实时刻对应。'),
S('跨学科迁移：用连续位置记录描述物体正在怎样运动','观察小车在0秒、1秒、2秒的位置，用箭头和刻度判断方向与快慢；再用The car is moving to the right和It is moving faster描述当前运动，区分某一时刻的位置与一段时间内的变化。'),
S('掌握检测与小结','视频通话显示：妈妈在厨房切菜，哥哥在客厅看书，墙上时间为18:30。选择语法、人物和现场证据均正确的报告，并说明一般习惯不能代替当前观察。',['Mum is cutting vegetables in the kitchen, and my brother is reading in the living room at 18:30.','Mum cuts vegetables now, and my brother reading.','They are at home, so they always do these actions.'],0,'通过：be动词、-ing形式、地点和时间证据全部准确。','尚未通过：按“主语—be—动作-ing—地点/时间”重新核对。')
],{subject:'物理与数学',title:'英语 × 运动观测：用位置—时间记录描述正在发生的运动',copy:'读取小车在0秒、1秒、2秒的刻度位置，判断方向和相邻时间段的位移变化；操作时间点后，用现在进行时报告小车此刻正在向哪里运动、速度是否变化。',labels:['读取三个时刻的位置刻度','比较位移判断方向与快慢','用现在进行时报告观测结果'],options:['先比较位置随时间的变化，再用is moving描述当前运动','只看某一张图就断定速度始终相同','只把move变成moving而不写be动词'],success:'完成：位置—时间数据给出运动证据，数学差值支持快慢判断，英语现在进行时报告正在发生的变化。'}),
'eng7b:4:1':L('怎样与他人分享生活：从照片、消息和时间信息读取事实并负责任地回应','能从生活动态中提取人物、地点、正在发生的活动、感受和发布时间；能用现在进行时写清楚现场，用一般现在时补充习惯，并在分享前检查时间语境、信息真实性和隐私边界。',{kind:'life-sharing-evidence',label:'切换照片、消息与时间戳，追踪“画面事实—文字说明—发布对象—合适回应”'},[
S('概念讲授：一条清楚的生活分享要回答四个问题','阅读照片或消息时依次确认Who、Where、What is happening和When。写动态时用可观察事实作核心，如We are planting trees at the school garden now，再补充感受或原因，不能让一句模糊标题代替事实。'),
S('正例1：从照片细节核对文字说明','照片时间为Saturday 9:20，学生戴手套、拿树苗和铲子。说明We’re planting trees in the school garden this morning与画面相符；回复可写Great work! Are you planting near the library?继续询问可核对信息。',['The post matches the photo: they are planting trees in the school garden.','They are swimming because the photo is outdoors.','They plant trees every day, so this must be a daily habit.'],0,'正确：动作、地点和时间都能从图文中找到证据。','不要把“在户外”直接推断成游泳，也不要把一次活动推成每天习惯。'),
S('正例2：区分此刻直播、旧照片与日常习惯','消息写“Photo from last Sunday”，即使照片里的人正在跑步，也应转述They were running in the photo或说明照片拍摄时的活动；若朋友实时视频说“Look!”，才用They are running now。时间戳决定叙述视角。',['This is an old photo, so it does not prove what they are doing now.','The photo shows running, so they are certainly running now.','Every shared photo must describe the current moment.'],0,'正确：先读发布时间和说明，再判断能否使用now。','照片内容与发布时刻可能不同，不能忽略时间语境。'),
S('反例与易错点：分享不是把所有个人信息都公开','把同学的家庭地址、实时位置和未经同意的正脸照片发到公开群组，会造成隐私与安全风险。应选择合适对象、征得同意，并删去与表达活动无关的敏感细节。',['Ask for permission and share only necessary activity information with the right audience.','Post everyone’s address so readers know the exact place.','A good caption must include a phone number and live location.'],0,'正确：表达活动不需要公开身份和精确位置等敏感信息。','判断“读者需要知道什么”，而不是“我能上传什么”。'),
S('教材型练习：为班级活动照片写有事实依据的动态与回复','照片显示三名学生正在图书馆整理书架，时间为16:10，分享对象是班级群。选择包含现场动作、地点、时间且不暴露多余个人信息的说明。',['We are putting books on the shelves in the school library at 4:10. Our class reading corner is getting ready!','Li Ming, phone 138…, is at the exact back door of the library now.','We always clean every library because this photo shows one activity.'],0,'正确：说明与图像吻合、对象合适，也没有公开无关敏感信息。','一张照片只能支持本次活动，不能证明always或every。'),
S('解释理由：为什么“看到—说明—回应”要形成证据链？','照片提供视觉事实，文字补充时间和目的，回应则应针对已有信息提出问题或反馈。三者相互核对可以减少误读；若时间、人物或地点不一致，应先询问而不是补写想象。'),
S('跨学科迁移：比较同一活动的原图、时间戳与文字元数据','读取三张校园活动卡的拍摄时间、发布时间、地点范围和说明，找出一条时间不一致、一条包含多余个人信息的记录；修改后生成“事实充分、时间明确、隐私适当”的英文发布卡。'),
S('掌握检测与小结','同学发来一张标注“yesterday”的篮球照片，却写We are playing basketball now，并附上另一位同学的电话号码。选择最恰当处理方式。',['Clarify that the photo is from yesterday, remove the phone number, and describe only the activity with permission.','Keep now because the people look active, and leave the number for detail.','Forward it publicly first and ask permission later.'],0,'通过：时间语境、事实表达、分享对象和隐私边界都处理正确。','尚未通过：先核对时间，再删去不必要个人信息，最后重写说明。')
],{subject:'信息科技与公民素养',title:'英语 × 媒体信息：核对时间戳并制作负责任的生活动态',copy:'比较照片拍摄时间、发布时间、可见活动和文字说明，发现时间错配或过度分享；在征得同意后，制作一张只保留必要信息的英文活动卡，并说明修改理由。',labels:['核对图像事实与时间戳','识别错配信息和隐私风险','重写英文说明并说明发布对象'],options:['先核对事实和时间，再征得同意并最小化个人信息','照片好看就直接公开实时位置','为了内容完整必须保留电话号码'],success:'完成：时间戳帮助判断叙述时态，媒体证据限制推断范围，英语把事实、感受和安全边界清楚表达。'}),
'eng7b:4:2':L('现在进行时：构造肯定、否定、一般疑问和特殊疑问并区分日常习惯','能掌握am/is/are + V-ing的肯定、否定、一般疑问和Wh问句；能处理make→making、run→running、lie→lying等拼写变化，并根据now与every day等时间线索区别现在进行时和一般现在时。',{kind:'present-continuous-lab',label:'改变主语、动作、句式和时间线索，观察be动词、-ing拼写与语序怎样联动'},[
S('概念讲授：现在进行时的核心是be动词加现在分词','肯定句She is writing；否定句She isn’t writing；一般疑问Is she writing?；特殊疑问What is she writing? 句式变化主要移动或否定be动词，动作的-ing形式保留。'),
S('正例1：由肯定句变为否定句和一般疑问句','They are watching a game. 否定为They aren’t watching a game. 一般疑问把are提前：Are they watching a game? —Yes, they are / No, they aren’t。',['They aren’t watching. Are they watching?','They don’t watching. Do they are watching?','They are not watch. Watching they are?'],0,'正确：否定加not，疑问把are移到主语前，watching不变。','进行时句式变化围绕be动词，不另加do/does。'),
S('正例2：按拼写规则写出现在分词','read→reading通常直接加-ing；make→making去不发音e；run→running重读闭音节双写末尾辅音；lie→lying把ie变y再加-ing。拼写规则服务于准确读写，不能只凭发音猜。',['making, running, lying','makeing, runing, lieing','making, runing, liying'],0,'正确：三类特殊变化分别处理准确。','先识别词尾结构，再决定去e、双写或ie变y。'),
S('反例与易错点：now与every day指向不同时间尺度','He is walking to school now描述此刻；He walks to school every day描述习惯。He is walking every day可能表达一段时期内的临时安排，但没有具体语境时不能把一般习惯机械改成进行时。',['He is walking now; he walks every day.','He walks now; he is walk every day.','He is walks now; he walking every day.'],0,'正确：时态依据意义和时间线索选择，不是看见动词就加-ing。','问自己：动作是在此刻展开，还是反复发生的习惯？'),
S('教材型练习：根据两条时间线索完成句子','Mia usually ___ (read) after dinner, but she ___ (talk) with her cousin on video now. 第一空是习惯，第二空是此刻正在进行。',['Mia usually reads after dinner, but she is talking with her cousin now.','Mia usually is reading, but she talks now.','Mia usually read, but she talking now.'],0,'正确：usually对应reads，now对应is talking。','先圈出时间词，再检查第三人称单数或be + -ing。'),
S('解释理由：为什么进行时需要be动词而不能只有-ing？','-ing形式本身不能承担限定动词的时态和主语一致信息；am/is/are标记当前时态并与主语配合。两部分合在一起，句子才同时说明“谁”以及“动作正在展开”。'),
S('跨学科迁移：比较匀速与加速小车的连续画面并写实验记录','读取每隔1秒拍摄的小车位置：若相邻位移相同，写The car is moving at a steady speed；若位移逐渐增大，写It is moving faster。用一般现在时写实验规律，用现在进行时写屏幕此刻现象。'),
S('掌握检测与小结','实验员每天检查轨道；屏幕上此刻小车正在向右加速。选择同时正确表达日常职责和当前现象的句子，并说明两种时态依据。',['The researcher checks the track every day, and the car is moving faster to the right now.','The researcher is checking every day, and the car moves faster now.','The researcher check every day, and the car moving now.'],0,'通过：一般现在时表示职责习惯，现在进行时表示当前可观察运动。','尚未通过：圈出every day与now，再分别匹配谓语结构。')
],{subject:'物理与数学',title:'英语 × 运动图像：区分实验规律与屏幕中的当前现象',copy:'读取小车每隔1秒的位置数据，比较相邻位移判断匀速或加速；用一般现在时陈述实验规律，用现在进行时描述屏幕此刻正在发生的运动。',labels:['计算相邻时间段的位移','判断匀速或加速现象','分别用两种时态写实验记录'],options:['数据差值判断运动，再按规律或当前现象选择时态','所有物理描述都只能用现在进行时','只看最后位置，不比较相邻时间段'],success:'完成：数学差值识别速度变化，物理模型解释运动，英语用两种时态区分稳定规律与当前现象。'}),
'eng7b:5:0':L('天气询问与现场播报：把天气现象、温度、地点和时间组织成准确报告','能识别sunny、cloudy、rainy、snowy、windy、foggy等天气词；能用What’s the weather like?、How’s the weather?询问，并结合温度计读数、地点与时间完成现场天气播报，区分当前观测与未来预报。',{kind:'weather-station',label:'切换城市、天气符号与温度计读数，观察现象、温度、时间和播报句怎样对应'},[
S('概念讲授：天气报告需要现象、温度、地点和时间四类信息','问What’s the weather like in Beijing?可答It’s cloudy and cool. The temperature is 18°C. 若报告当前降雨，可说It’s raining now。地点和时间限定结论，不能把一个城市此刻的天气当成整天或全国天气。'),
S('正例1：由天气符号和温度计读数生成现场播报','上海14:00显示乌云、雨滴和22°C，可播报It’s rainy in Shanghai at 2 p.m. It’s 22 degrees Celsius. Take an umbrella. 建议来自可见降雨信息，不是凭空添加。',['It’s rainy in Shanghai at 2 p.m., and the temperature is 22°C.','Shanghai is snowing at −5°C because the icon has a cloud.','It is 22 weather and rain every day.'],0,'正确：地点、时间、现象和温度读数完全对应。','云朵图标要结合雨滴、雪花等细节判断，温度要带单位。'),
S('正例2：比较两个城市而不混淆数据','北京8°C且有风，广州26°C且晴。可说It’s windy and cool in Beijing, but it’s sunny and warm in Guangzhou. 两组形容词、温度和城市必须成对，不能串行。',['Beijing is windy at 8°C, while Guangzhou is sunny at 26°C.','Beijing is sunny at 26°C, and Guangzhou is windy at 8°C.','Both cities have the same weather because it is the same day.'],0,'正确：每个城市都保留了自己的现象和温度。','比较时先制作“城市—符号—温度”对应表，再连接成句。'),
S('反例与易错点：当前观测与未来预报不能混为一谈','Now: cloudy, 16°C；Tomorrow: rainy, 12°C。应说It is cloudy now. It will be rainy tomorrow. 若把tomorrow写成is raining now，就改变了信息的时间属性。',['It is cloudy now, and it will be rainy tomorrow.','It is raining tomorrow now.','It will cloudy now and is rain tomorrow.'],0,'正确：now与tomorrow分别匹配当前状态和未来预报。','先圈出时间，再决定是当前观测还是未来预报。'),
S('教材型练习：根据校园气象卡完成早间播报','7:30校园观测：12°C、薄雾、微风；午后预报：20°C、晴。选择同时呈现当前情况、温度变化和合理提醒的播报。',['It is foggy and cool at 7:30, at 12°C. It will be sunny and warmer this afternoon, around 20°C.','It is sunny at 20°C now because that is the afternoon forecast.','The weather is 12 fog and the school will always be sunny.'],0,'正确：当前观测与午后预报分开表达，温度和时间都准确。','预报不是当前事实，温度数字必须和对应时段绑定。'),
S('解释理由：为什么仅说hot或cold不够精确？','冷热感受会受季节、风速、湿度和个人状态影响。加入温度、地点与时间后，报告才可核对、可比较；形容词负责体验，测量值负责客观证据，两者不能互相替代。'),
S('跨学科迁移：读取一日温度曲线并确定升温和降温时段','记录8时、11时、14时、17时的温度为12、17、21、18°C，计算相邻时段温差，判断何时升温最快、何时开始降温，再用英语完整播报变化及时间范围。'),
S('掌握检测与小结','气象卡显示：成都9:00阴天15°C；14:00预报小雨18°C。选择区分当前与预报、正确读取摄氏温度并给出有依据提醒的播报。',['It is cloudy in Chengdu at 9 a.m., at 15°C. Light rain is forecast for 2 p.m., around 18°C, so take an umbrella.','It is raining at 9 a.m. and 18°C because rain appears later.','Chengdu is always cloudy and the temperature is 15 weather.'],0,'通过：现象、温度、地点、时间和预报边界全部准确。','尚未通过：把当前栏和预报栏分开，再逐项配对。')
],{subject:'物理与数学',title:'英语 × 温度曲线：读取气温变化并完成分时天气播报',copy:'读取8时、11时、14时、17时的摄氏温度，计算相邻时段温差并判断升温、最高点和降温；操作时间点后，用英语报告该时段的天气现象和温度变化。',labels:['读取时间与摄氏温度','计算相邻时段温差','用英语播报变化与时间范围'],options:['先按时间配对读数，再计算温差并报告趋势','只看最高温就描述整天变化','把摄氏度数字直接当作天气形容词'],success:'完成：温度计提供测量值，数学差值揭示变化趋势，英语把地点、时间、现象和数据组织成可核对播报。'}),
'eng7b:5:1':L('天气怎样影响感受与活动：从人物、条件和记录提出有边界的计划','能从短文或对话中提取天气、人物感受、活动变化和理由；能用feel、make、because、so和适当建议建立“天气条件—身体感受—活动选择”证据链，同时避免把个人感受当作所有人的必然反应。',{kind:'weather-feeling-map',label:'切换人物与天气记录，连接气温、风雨、个人感受、活动计划和安全调整'},[
S('概念讲授：描述天气影响要把条件、感受和行动连成证据链','It’s hot and humid, so Leo feels tired and moves football practice indoors. 天气是条件，tired是人物感受，调整场地是行动。合理表达保留人物差异，不说Hot weather makes everyone unhappy。'),
S('正例1：从日记证据解释人物选择','Anna写道：It is windy and 9°C. My hands feel cold, so I am wearing gloves and taking a shorter walk. 结论来自温度、风和她自己的感受，行动具体且可以执行。',['Anna feels cold, so she is wearing gloves and shortening her walk.','Everyone feels cold whenever it is windy.','Anna is ill because the temperature is 9°C.'],0,'正确：只报告Anna的记录，不把感受扩大为普遍结论或疾病诊断。','区分可观察天气、本人感受和不能由记录推出的结论。'),
S('正例2：同一天不同人物可以作出不同活动选择','午后28°C且晴，Ben想游泳，Mei怕晒选择室内羽毛球。可说The sunny weather makes Ben excited, but Mei prefers an indoor activity because she wants shade. 同一条件不保证相同感受。',['Ben chooses swimming, while Mei chooses indoor badminton for shade.','Both students must swim because the weather is sunny.','Mei dislikes all outdoor activities forever.'],0,'正确：两人的感受与计划分别由文本证据支持。','天气影响选择，但个人偏好和目的仍需单独读取。'),
S('反例与易错点：because与so不能在同一简单因果句中重复堆叠','Because it is raining, we are staying inside. 或It is raining, so we are staying inside都正确；Because it is raining, so…重复标记因果。建议还应与强度相称，不能把小雨自动写成灾害。',['Because it is raining, we are staying inside.','Because it is raining, so we are staying inside.','It raining, because we stays inside.'],0,'正确：使用一个清楚的因果连接方式，主谓形式也正确。','选because或so中的一个，再核对天气事实与行动是否相称。'),
S('教材型练习：依据周末天气和个人条件调整活动计划','周六上午18°C小雨，下午23°C转晴；班级计划骑行，但一名同学没有雨具。选择既读取分时预报，又提供可执行备选方案的表达。',['It is raining in the morning, so we can move the ride to the sunny afternoon and check that everyone has safe equipment.','It rains in the morning, so the whole weekend is impossible.','Because one student has no raincoat, so nobody can ever ride.'],0,'正确：计划依据分时天气调整，并考虑成员条件与装备。','先定位天气发生的时段，再设计具体替代时间或场地。'),
S('解释理由：为什么天气建议必须注明对象、时段和依据？','“天气不好，别出去”信息不足。说明Saturday morning、light rain、18°C以及活动类型，才能判断是改时间、换场地还是增加装备；建议越具体，越能被执行和复盘。'),
S('跨学科迁移：比较风速与体感记录，设计可复核的活动方案','读取相同10°C下风速2、12、25 km/h的三次记录以及学生体感评分，找出风速与体感变化的关系；为操场活动选择时段、服装和备选场地，并用英语说明数据依据与个体差异。'),
S('掌握检测与小结','周日10:00为10°C、风速25 km/h；15:00为16°C、风速6 km/h。团队中有人对强风敏感。选择最有证据且不过度推断的计划。',['The afternoon is warmer and less windy, so it may suit the team better; bring layers and confirm how everyone feels.','Strong wind means everyone will become ill, so cancel all outdoor plans forever.','Choose 10 a.m. because temperature and wind never affect comfort.'],0,'通过：时段数据、人物差异、行动方案和谨慎表述都完整。','尚未通过：比较两个时段的数据，再把建议限制在本次活动。')
],{subject:'物理与健康教育',title:'英语 × 风与体感：用测量数据调整户外活动计划',copy:'比较相同气温下不同风速与同学体感评分，判断强风如何改变散热感受；为班级户外活动选择时段、服装和备选场地，并用英语说明数据依据与个体差异。',labels:['读取温度、风速和体感评分','比较数据并识别个体差异','制定英语活动方案与备选措施'],options:['综合温度、风速和个人记录，提出可调整方案','只看一个人的感受就代表全班','把强风直接判断为所有人生病'],success:'完成：物理数据解释风与散热条件，健康记录保留个人差异，英语把证据转成具体而不过度的活动建议。'}),
'eng7b:5:2':L('天气语境中的现在进行时：区分天气状态、正在发生的现象和临时活动','能区分It is rainy与It is raining、It is snowy与It is snowing；能用现在进行时描述天气变化和人物临时活动，构造否定句、一般疑问句与Wh问句，并与一般现在时表示的季节规律或习惯区分。',{kind:'weather-progressive-lab',label:'改变天气状态、实时现象、人物活动与时间线索，观察形容词、be + V-ing和一般现在时怎样分工'},[
S('概念讲授：天气形容词描述状态，be + 天气动词-ing强调正在发生','It is rainy描述天气状态；It is raining强调雨正在下。Look! The wind is blowing and people are opening umbrellas把天气现象与现场动作放在同一时刻。选择结构前要先判断想表达状态还是过程。'),
S('正例1：从肯定句构造否定句和一般疑问句','It is snowing. 否定为It isn’t snowing. 一般疑问为Is it snowing? —Yes, it is / No, it isn’t。变化仍围绕be动词，snowing保持不变。',['It isn’t snowing. Is it snowing?','It doesn’t snowing. Does it snowing?','It not is snowing. Snowing it is?'],0,'正确：否定加not，疑问把is移到主语it之前。','不要为进行时另加do/does，先找到原句中的is。'),
S('正例2：用Wh问句同时询问天气下的人物活动','—What are the children doing in the rain? —They are jumping over puddles. —Where is their teacher standing? —She is standing under a shelter. 问词决定缺少的信息，be动词与主语一致。',['What are the children doing? Where is the teacher standing?','What do the children doing? Where the teacher is standing?','What are the children do? Where does the teacher standing?'],0,'正确：Wh词后保持一般疑问语序，再接动词-ing。','问词不替代be动词；多人用are，单数人物用is。'),
S('反例与易错点：季节规律、天气预报和眼前现象使用不同表达','It often rains here in summer表示规律；It is raining now表示眼前现象；It will rain tomorrow表示预报。把often rains写成is often raining会改变为临时反复情形，需要特殊语境。',['It often rains in summer, and it is raining now.','It is often rain in summer, and it rains now at this moment.','It often raining in summer, and it is rain now.'],0,'正确：规律用一般现在时，当前过程用现在进行时。','先识别often、in summer、now、tomorrow等时间线索。'),
S('教材型练习：根据气象屏和街景完成双层描述','资料显示本地春季通常多风；直播街景中树枝正在摇动，人们正抓紧帽子。选择同时说明季节规律和当前画面的句子，并分别标出规律与现场证据。',['It is often windy here in spring. Right now, the wind is blowing hard and people are holding their hats.','The wind is always blowing now, and people hold hats at this moment.','It often is blow in spring, and people are hold their hats.'],0,'正确：稳定规律与直播现象分别选择合适结构。','一条句子回答“通常怎样”，另一条回答“此刻正在怎样”。'),
S('解释理由：为什么It is rainy与It is raining意思相近但不完全相同？','rainy是形容词，给天气贴上状态标签；is raining是进行时，把降雨看作正在展开的过程。天气报告可根据任务选择：概括全天状态时用rainy，报道眼前变化时用raining。'),
S('跨学科迁移：读取温度与降水连续观测，描述天气正在怎样变化','查看每30分钟的温度、雨量和云量：温度从20降到16°C、雨量从0增至4毫米。用一般现在时说明读数规则，用现在进行时报告The temperature is falling and the rain is getting heavier。'),
S('掌握检测与小结','地区秋季通常凉爽；直播显示气温正从18°C降到14°C，雨正在增强，学生正移入室内。选择同时准确表达规律、变化与人物行动的报告。',['It is usually cool here in autumn. The temperature is falling, the rain is getting heavier, and the students are moving indoors now.','It is falling every autumn, and the students move indoors now.','The temperature falls now and the rain getting heavier because autumn always rains.'],0,'通过：一般规律、连续变化和当前行动三层信息分别表达准确。','尚未通过：先标出usually与now，再选择一般现在时或be + V-ing。')
],{subject:'物理与数学',title:'英语 × 连续观测：用温度与雨量序列描述天气正在变化',copy:'读取每30分钟的温度、雨量和云量记录，计算温度差并判断降雨是增强还是减弱；用一般现在时说明读数规则，用现在进行时报告屏幕中正在发生的变化。',labels:['读取连续温度与雨量数据','计算差值判断变化方向','分别写规律说明和当前报告'],options:['比较相邻读数，再按规律或当前变化选择时态','只看最后一个读数就描述全过程','所有带天气词的句子都使用进行时'],success:'完成：连续数据证明变化方向，物理量限制结论，英语用一般现在时与现在进行时分别表达规则和正在发生的过程。'}),
'eng7b:6:0':L('难忘的一天：用过去的时间、地点、人物和感受复原完整经历','能听懂并询问What was your special day like?；能用was/were描述过去的天气、地点、人物状态和感受，并按时间证据区分活动发生前、发生时和结束后的信息。',{kind:'special-day-timeline',label:'切换时间卡、照片和人物感受，观察was/were怎样把过去场景串成完整经历'},[
S('概念讲授：过去经历先确定时间，再用was或were建立场景','Last Saturday是过去时间；I/He/She/It搭配was，You/We/They搭配were。完整开场可写Last Saturday was our school art day. We were excited because the hall was full of student work。'),
S('正例1：从票根和照片复原活动信息','票根写5 May 10:00，照片显示Lily和父母在科技馆。可问Where were they? 回答They were at the science museum. Lily was curious and happy。地点、人物和感受都有证据。',['They were at the science museum on 5 May, and Lily was curious.','They was at school tomorrow, and Lily were curious.','The museum is there, so they are there now.'],0,'正确：复数主语用were，单数Lily用was，时间明确在过去。','先标出人物数量和过去时间，再选择was或were。'),
S('正例2：同一天不同阶段的状态会变化','比赛前Tom was nervous；获胜后Tom and his teammates were proud。感受变化必须绑定时间节点，不能把nervous和proud当作同时不变的标签。',['Tom was nervous before the match, but the team were proud after it.','Tom were nervous and the team was proud.','Tom is nervous last week and they are proud yesterday.'],0,'正确：单数Tom用was，复数team members的语境用were，前后节点清楚。','人物数量与时间节点都要核对。'),
S('反例与易错点：ago、last和yesterday不能搭配现在时','Yesterday the weather was sunny正确；Yesterday the weather is sunny错误。was/were描述过去状态，不表示过去发生的动作；“参观”仍需visited等过去式，不能只靠was。',['The weather was sunny, and we visited the old town yesterday.','The weather is sunny yesterday, and we were visit the town.','We was at the town and are happy last Sunday.'],0,'正确：过去状态用was，过去动作另用visited。','区分“是什么状态”和“做了什么动作”。'),
S('教材型练习：根据毕业日资料卡写三句场景复原','资料卡：20 June、school hall、parents and teachers、happy but nervous。选择包含日期、地点、人物和两种感受且主谓一致的描述。',['On 20 June, we were in the school hall. Our parents and teachers were there, and I was happy but nervous.','On 20 June, I were happy and everyone was teachers.','We are in the hall last June and I was be nervous.'],0,'正确：日期、地点、人物与感受均对应资料卡。','不要把信息堆成词组，要用was/were建立完整句。'),
S('解释理由：为什么回忆不能只列“happy、museum、Saturday”？','词汇清单没有说明谁在什么时间和地点处于何种状态。was/were把人物与状态连接，时间和地点则限定事件；四类信息齐全，听者才能复原经历而不是猜。'),
S('跨学科迁移：把照片时间戳和气温记录放到同一时间轴','三张照片时间为9:00、11:30、15:00，对应气温12、18、16°C。按时间排序，说明上午哪里最暖、人物当时在哪里和感受如何，再用was/were写三句证据报告。'),
S('掌握检测与小结','记录显示：去年10月2日，上午在山脚12°C，下午在观景台18°C；Mia先紧张后兴奋。选择时间、地点、温度和was/were全部准确的复原。',['Mia was nervous at the foot of the hill in the morning, but she and her friends were excited at the viewpoint in the afternoon.','Mia were nervous and her friends was excited tomorrow.','They are at the viewpoint last year because it is 18°C.'],0,'通过：人物数量、过去时间、地点和感受变化均准确。','尚未通过：先画时间轴，再为每个节点选择was或were。')
],{subject:'数学与地理',title:'英语 × 时间轴：把照片、地点和气温还原为一天的经历',copy:'按三张照片的时间戳排序，将地点和气温读数放入同一时间轴；比较温差后，用was/were写出人物在每个时刻的位置、天气与感受。',labels:['排序照片时间戳','配对地点与气温并比较','用was/were写证据报告'],options:['先按时间排序，再逐点配对人物、地点和温度','只选最好看的照片作为全部经历','把所有过去节点都用is/are描述'],success:'完成：数学时间轴确定先后，地理与气温数据复原场景，英语用was/were准确记录过去状态。'}),
'eng7b:6:1':L('从特别经历中学到了什么：用事件、困难、行动和结果支持反思','能从日记或采访中提取发生了什么、遇到什么困难、采取什么行动和得到什么结果；能用first、then、finally、because和learned建立证据链，避免只有空泛的“很有意义”。',{kind:'memory-evidence-chain',label:'切换经历片段，连接困难、行动、结果和从中学到的道理'},[
S('概念讲授：反思必须回答“发生—应对—结果—所学”','I learned to work as a team只有结论。更完整的是The model fell apart, so we divided the jobs and rebuilt it. It worked, and I learned that clear roles help a team。道理必须由具体事件支持。'),
S('正例1：从志愿活动记录提取成长证据','开始时Ben was shy，不敢向陌生人介绍旧书；同伴先示范，他随后完成三次介绍。可写He learned that practice and support can build confidence，依据是可观察的尝试次数。',['Ben was shy, but after practising three introductions, he became more confident.','Ben learned everything because the day was special.','Ben was never shy because he spoke once.'],0,'正确：困难、行动与变化均有记录支持。','不要从一次行为推出永久性人格结论。'),
S('正例2：一次失败也能提供可验证的学习','纸桥第一次承重200克后倒塌；小组加三角支撑，第二次承重450克。可反思They learned to test, record and improve a design rather than simply saying失败很有趣。',['The second bridge held 250 g more, so the team learned to improve from test data.','The bridge was perfect because it failed first.','The team learned nothing because the first test failed.'],0,'正确：数据差值支持“测试—改进—再验证”的反思。','失败是证据的一部分，关键是后续行动和结果。'),
S('反例与易错点：事件顺序与因果关系不能倒置','First we tested the bridge. Then it fell. Finally we added supports顺序错误，因为改进应发生在第二次测试前。连接词不是装饰，必须符合真实时间线。',['First we tested it; then we added supports; finally the new bridge held more weight.','Finally we began, first we finished, then we planned.','Because it improved, so we changed it before testing.'],0,'正确：时间连接词与实验步骤一致，因果只标记一次。','先排序事件卡，再选择first、then、finally。'),
S('教材型练习：依据迷路经历写出有证据的反思','日记：地图离线、路标被忽略；学生停下、返回最后一个路标并向工作人员求助，最终安全到达。选择同时概括困难、有效行动、结果以及下次可复用策略的学习总结。',['We learned to check the map before leaving, follow signs, and ask for help when unsure.','We learned that all trips are dangerous and maps are useless.','It was memorable because it was memorable.'],0,'正确：建议逐一回应了记录中的问题和有效行动。','反思应能指导下次行动，而不是夸大或重复标题。'),
S('解释理由：为什么“我学到了坚持”还不够？','抽象品质需要行为证据：尝试了几次、改变了什么方法、结果如何。把品质和可观察行动连接，读者才能判断结论是否成立，学习者也能在新任务中复用策略。'),
S('跨学科迁移：用纸桥承重数据写实验反思','比较第一次200克与改进后450克的承重，计算增加量和增长比例；指出三角支撑这一变量，再用英语按first—then—finally写实验过程和从证据中学到的设计原则。'),
S('掌握检测与小结','模型车第一次因车轮不齐偏向左侧；小组只调整轮距，第二次直行3米。选择包含最初困难、单一变量调整、量化结果和下次可复用学习结论的完整反思。',['The car first turned left. We aligned the wheels, and it then travelled straight for 3 m. We learned to change one variable and test again.','The car was bad, but then it was good, so science is easy.','It went straight once, which proves every car is perfect.'],0,'通过：事件、变量、数据结果和可迁移结论完整。','尚未通过：补出改了什么、结果如何以及下次可复用的策略。')
],{subject:'数学与工程实践',title:'英语 × 工程迭代：用承重数据写一次有证据的学习反思',copy:'比较纸桥改进前后的承重数据，计算增加量并识别三角支撑这一变量；按first、then、finally写实验过程，再用learned说明数据支持的设计原则。',labels:['读取两次承重数据','计算改进量并识别变量','写过程与证据反思'],options:['用数据和单一变量支持反思结论','只写成功很开心，不说明改进','第一次失败就停止并删除记录'],success:'完成：工程迭代提供行动与结果，数学量化改进，英语把经历转化为可复用的学习策略。'}),
'eng7b:6:2':L('一般过去时be动词：掌握was/were的肯定、否定、疑问和简答','能依据主语选择was或were；能构造wasn’t/weren’t、Was/Were…?和Where/How…?问句；能用过去时间线索作答，并区分be动词状态句与过去动作句。',{kind:'past-be-lab',label:'改变主语、过去状态和句式，观察was/were、否定词和疑问语序怎样联动'},[
S('概念讲授：was/were是am/is/are的过去式','I/he/she/it用was，you/we/they用were。肯定She was tired；否定She wasn’t tired；疑问Was she tired? 特殊疑问Where was she? 变化围绕was/were完成。'),
S('正例1：从肯定句变为否定句和一般疑问句','They were at the museum. 否定They weren’t at the museum. 疑问Were they at the museum? —Yes, they were。复数主语全程保持were。',['They weren’t there. Were they there?','They didn’t were there. Did they were there?','They was not there. Was they there?'],0,'正确：否定加not，疑问把were提前，不使用did。','be动词过去式可以自行构造否定和疑问。'),
S('正例2：特殊疑问词决定需要的信息','回答At the sports centre对应Where were you?；回答Because the final was exciting对应Why were you excited?；回答Cold but sunny对应What was the weather like?',['Where were you? Why were you excited? What was the weather like?','Where did you were? Why you was excited?','What were the weather like? Where was you?'],0,'正确：问词、主语与was/were全部对应答案类型。','先看答案缺少的是地点、原因还是天气。'),
S('反例与易错点：有was/were时不再添加did','Did she was happy错误，应为Was she happy? 但询问动作Did she visit the museum?需要did + 动词原形。判断谓语是状态还是动作，决定疑问结构。',['Was she happy? Did she visit the museum?','Did she was happy? Was she visit the museum?','Was she happy? Did she visited the museum?'],0,'正确：状态句用was提问，动作句用did + 原形。','先圈出谓语核心：be状态还是实义动作。'),
S('教材型练习：完成过去状态采访','采访信息：Leo昨天下午在图书馆，和两位朋友一起，心情平静。选择能够正确询问地点与同伴、准确回答感受，并且所有was/were都与主语单复数一致的一组句子。',['Where was Leo? Who were with him? He was calm.','Where did Leo was? Who was his two friends? He were calm.','Where is Leo yesterday? He did calm.'],0,'正确：单数Leo用was，两位朋友用were，过去时间一致。','疑问词之后仍需检查主语单复数。'),
S('解释理由：为什么was/were问句不使用did？','英语中的be动词能直接承担时态、主语一致和疑问倒装；did用于帮助普通动作动词构造过去时疑问。重复使用会出现两个过去标记，结构错误。'),
S('跨学科迁移：根据历史温度表询问过去天气','温度表记录周一8°C、周二12°C、周三6°C。用What was the temperature…?和Was it warmer…?提出问题，比较哪天更暖，并用was/were给出含数据的回答。'),
S('掌握检测与小结','资料：上周五学生们在实验室，实验过程并不容易，但最终结果令人兴奋。选择同时包含过去状态陈述、正确否定、一般疑问和简短回答的完整组合。',['The students were in the lab. The task wasn’t easy. Were they excited by the result? Yes, they were.','The students was in the lab. The task didn’t was easy.','Did the students were in the lab? Yes, they did were.'],0,'通过：复数主语、否定、倒装和简答全部正确。','尚未通过：找到每句主语，再决定was或were及其位置。')
],{subject:'数学与地理',title:'英语 × 历史气温表：用was/were比较过去三天的天气',copy:'读取周一至周三的气温和天气记录，比较最大值、最小值与温差；用What was…?、Was it…?和was/were回答过去天气问题。',labels:['读取过去三天数据','比较温度并形成问题','用was/were完整问答'],options:['先按日期配对数据，再用was/were提问和比较','把过去数据全部改写成现在时','用did was重复标记过去'],success:'完成：历史数据提供过去事实，数学比较确定差异，英语用was/were完成准确询问与回答。'}),
'eng7b:7:0':L('喜爱的故事：从人物、背景、目标、冲突和结局复述故事主线','能询问What are your favourite stories?并说明理由；能从寓言、童话或民间故事中提取character、setting、goal、problem、key events和ending，用过去时按顺序复述，不把个人评价当成原文事实。',{kind:'story-plot-map',label:'切换故事卡与情节节点，追踪人物目标、困难、行动和结局怎样构成主线'},[
S('概念讲授：复述故事不是罗列角色，而是建立因果情节','故事主线可用Who wanted what—What stopped them—What they did—How it ended。以《龟兔赛跑》为例，兔子想赢却中途睡觉，乌龟持续前进，最后先到终点。'),
S('正例1：从文本证据区分人物目标和行动','文本写The fox wanted the grapes. He jumped several times but could not reach them. 目标是得到葡萄，行动是跳跃，结果是没有够到；不能把“狐狸讨厌葡萄”放在开头。',['The fox wanted the grapes, tried to reach them, but failed.','The fox hated the grapes before he saw them.','The grapes jumped, so the fox won.'],0,'正确：目标、尝试和结果按原文顺序。','人物后来的说法不能倒推成最初目标。'),
S('正例2：setting会限制人物可采取的行动','故事发生在暴风雪中的山路，人物选择寻找山洞而不是继续露营。可说The storm made the road unsafe, so they looked for shelter。背景条件解释行动。',['The storm made the road unsafe, so they looked for shelter.','They looked for a classroom because every story happens at school.','The setting does not affect any event.'],0,'正确：环境条件与人物选择形成因果。','地点和天气不是装饰，应检查它们如何推动情节。'),
S('反例与易错点：复述要保持视角和时态一致','The boy opened the box and sees a bird混合过去与现在；应为opened and saw。引用角色原话可保留引号内时态，但叙述主线通常统一用过去时。',['The boy opened the box and saw a bird.','The boy opens the box and saw a bird yesterday.','The boy was open the box and see a bird.'],0,'正确：两个连续过去动作形式一致。','先确定叙述时间，再逐个检查动作动词。'),
S('教材型练习：从六张图片选出完整故事顺序','图片依次显示女孩发现受伤小鸟、制作纸箱小窝、喂水、联系救助站、小鸟逐渐恢复并最终放飞。选择同时交代起因、连续行动、恢复过程和结局的完整复述。',['A girl found an injured bird, cared for it and contacted a rescue centre. After it recovered, she released it.','A bird flew away, so the girl found it before it was injured.','There was a girl and a bird. It was interesting.'],0,'正确：情节顺序、关键行动与结局完整。','只列角色和评价不能构成故事主线。'),
S('解释理由：为什么故事地图要区分goal、problem和action？','目标说明人物想要什么，困难解释为什么不能立刻实现，行动连接选择与结果。若三者混在一起，复述会遗漏因果，读者也无法理解结局为何发生。'),
S('跨学科迁移：把科学发现史整理成故事情节图','根据“问题—观察—假设—实验—结果”卡片复述一次科学发现：人物目标是解释现象，冲突是旧解释不符数据，行动是设计实验，结局是得到更可靠模型。'),
S('掌握检测与小结','故事资料：村民缺水；女孩观察到清晨树叶有水珠，搭建收集装置，三天得到6升水。选择同时包含背景、目标、行动、数据结果和结局的复述。',['The village needed water. The girl noticed dew, built a collector and gathered 6 litres in three days, so the villagers tested a larger one.','The village had enough water, so the girl did nothing and collected 6 litres.','A girl liked science. The story was good.'],0,'通过：人物、问题、行动、量化结果和后续结局完整。','尚未通过：用五格故事地图补齐缺失环节。')
],{subject:'科学史与信息组织',title:'英语 × 科学发现史：用故事地图复原“问题—实验—证据—模型”',copy:'将科学发现材料拆成问题、观察、假设、实验和结果五张卡，按因果顺序排列；用过去时复述人物如何用数据修正解释，并标明史实与后人评价。',labels:['识别人物目标与科学问题','排列实验和证据顺序','用过去时复述模型变化'],options:['按史料证据排序并区分事实与评价','为了精彩随意添加人物台词','只记科学家姓名不说明实验'],success:'完成：故事结构组织科学史，实验数据支撑转折，英语过去时清楚复原发现过程。'}),
'eng7b:7:1':L('故事能教会我们什么：用关键选择与结果支持主题判断','能从人物反复行为、关键选择和结局推断主题；能用The story teaches us… because…表达道理，并引用具体事件作证；能比较不同解释，避免把一句口号强加给任何故事。',{kind:'story-theme-evidence',label:'切换人物选择与结局，观察“行动—后果—主题—现实任务”怎样连接'},[
S('概念讲授：主题不是标题，而是由关键选择与后果支持的解释','说The story teaches us to be honest，需要指出人物说谎造成什么后果、诚实选择又改变了什么。主题应解释多个关键事件，而不是只匹配一个好听的词。'),
S('正例1：用两个事件支持“合作”主题','两兄弟单独搬石头都失败；他们后来用木杆一起抬起。主题可写Cooperation can solve a problem that is too hard for one person，两个事件形成对照证据。',['The story values cooperation because both failed alone but succeeded together.','The story is about strength because there is a stone.','The story proves two people always win every task.'],0,'正确：主题解释了前后对照，又没有夸大为绝对规律。','道具不是主题，结论范围不能超过故事证据。'),
S('正例2：同一故事可以有不同但有依据的解释','角色归还钱包后失主帮助他，也可解释为诚实建立信任，或善意带来互助。只要引用关键选择与结果，两种主题都可能成立。',['Honesty builds trust because returning the wallet led to mutual help.','Money is the only theme because a wallet appears.','The character was perfect, so every action was right.'],0,'正确：主题由行为与后果支持，并保留解释空间。','不要把故事物件等同主题，也不要把人物神化。'),
S('反例与易错点：不能只凭结局判断人物所有选择','主人公最后成功，不代表过程中的冒险都正确。应分别评价每个选择的条件与后果，并说明主题是鼓励勇气、谨慎还是求助，不能写“成功者做什么都对”。',['Evaluate each choice with its conditions and consequences.','The ending is happy, so every risky choice was correct.','The hero won, which proves rules never matter.'],0,'正确：结局是证据之一，不会自动洗白所有行为。','回到关键选择，逐一检查短期和长期后果。'),
S('教材型练习：从《狼来了》事件选择最有证据的主题','男孩两次谎报警情，村民也两次放下工作赶来；真正危险发生时，他再次求助却无人相信。选择能够同时解释重复谎言、信任下降和最终求助失败的主题。',['Repeated lies can destroy trust, so people may not believe the truth later.','Never ask anyone for help, because help is useless.','Sheep are dangerous animals and should not live near villages.'],0,'正确：谎言—信任下降—真实求助失败构成完整证据链。','主题要解释人物选择和结果，不是挑一个故事名词。'),
S('解释理由：为什么主题判断允许多个答案却不能随意？','文学解释可以从不同角度概括，但必须满足证据约束：解释关键事件、与结局不冲突、范围不过度。观点不同不等于无需证据。'),
S('跨学科迁移：把寓言主题转化为校园中的可操作任务','选择“合作”或“诚信”主题，在小组实验中设计一条可观察规则，例如每次记录由两人复核；执行后比较错误数，再用英语说明故事概念如何通过数据得到现实检验。'),
S('掌握检测与小结','故事中学生第一次独自做实验时漏记三项数据；第二次明确分工并进行交叉检查，遗漏降为零。选择既有量化证据、又不过度概括的主题与现实迁移结论。',['Clear roles and checking can improve teamwork, as the second test reduced missing records from three to zero.','Working alone is always wrong in every situation.','The theme is “laboratory” because the story happens there.'],0,'通过：关键选择、量化后果、主题和迁移任务一致。','尚未通过：主题必须解释三项遗漏如何降为零。')
],{subject:'数学与科学实践',title:'英语 × 证据推理：用实验错误率检验故事中的“合作”主题',copy:'把故事中的合作原则转为实验分工与交叉检查规则，记录改进前后的漏记项数量；比较数据后，用because说明主题通过什么操作和结果得到现实支持。',labels:['把主题转为可观察规则','记录并比较错误数量','用英语说明证据与限制'],options:['设计可执行规则并用前后数据检验','只抄故事口号不执行任务','一次成功就断言合作永远最好'],success:'完成：故事主题提出假设，实验任务产生数据，英语用因果表达说明主题在具体条件下如何成立。'}),
'eng7b:7:2':L('一般过去时实义动词：掌握规则、不规则形式及did问答','能构造规则动词-ed和常见不规则过去式；能用didn’t + 原形、Did… + 原形以及Wh + did提问；能依据过去时间线索保持叙述时态一致，并区分was/were状态句。',{kind:'simple-past-action-lab',label:'改变动作、过去式类型和句式，观察-ed、不规则变化、did与动词原形怎样配合'},[
S('概念讲授：肯定句标记过去，did问答把动作恢复原形','肯定They visited the castle；否定They didn’t visit it；疑问Did they visit it? —Yes, they did。did已经标记过去，后面的动作必须使用原形。'),
S('正例1：规则动词过去式要同时处理拼写与读音','play→played，live→lived，stop→stopped，study→studied。-ed可读/t/、/d/或/ɪd/，但书写规则由词尾结构决定。',['played, lived, stopped, studied','playd, liveed, stoped, studyed','played, lived, stoppped, studyd'],0,'正确：直接加-ed、去e加-d、双写、辅音+y变ied分别准确。','先分类词尾，再写过去式。'),
S('正例2：常见不规则过去式需要在语境中记忆','go→went，see→saw，take→took，find→found。可写The girl went into the forest, saw a light and found a small house，三个动作按顺序统一在过去。',['went, saw, found','goed, seed, finded','went, see, founded'],0,'正确：不规则形式与故事顺序都准确。','found是find的过去式；founded通常意为“创立”。'),
S('反例与易错点：did后不能再使用过去式','Did the boy found the key?错误，应为Did the boy find the key? He didn’t found也应改为didn’t find。肯定回答He found it才使用过去式。',['Did he find it? He didn’t find it at first, but he found it later.','Did he found it? He didn’t found it.','Did he finded it? He not found it.'],0,'正确：did问答用原形，独立肯定句用found。','每句只能保留一个过去标记。'),
S('教材型练习：根据故事图完成过去时问答','图示女孩先发现钥匙不在书包里，随后沿路寻找，最后在公园长椅下找到。选择同时包含正确Wh问句、didn’t否定和独立肯定过去式的完整叙述。',['Where did she find the key? She didn’t find it in her bag; she found it under a bench.','Where did she found the key? She didn’t found it.','Where was she find the key? She finded it under a bench.'],0,'正确：did后用find，肯定句使用found。','问句、否定句和肯定句要分别检查动词形式。'),
S('解释理由：为什么did出现后动词必须恢复原形？','did已经承担过去时标记和疑问或否定功能。如果动作词再用过去式，就重复标记过去。原形保留动作词义，did负责语法。'),
S('跨学科迁移：用过去时复述一次控制变量实验','实验组先测100毫升热水自然冷却，再加盖重复测量。用measured、covered、fell、did not fall等过去式记录步骤和结果，按时间表复述而不把相关性夸大成唯一原因。'),
S('掌握检测与小结','实验记录：研究者测量两杯水的初温，只给其中一杯加盖；十分钟后有盖组下降4°C，未加盖组下降9°C。选择过去式、did问句、数据比较和谨慎结论全部正确的报告。',['They measured both cups. They covered one cup, and its temperature fell 4°C. The uncovered cup fell 9°C. Did the cover slow the cooling? The data suggest it did.','They measure yesterday and did covered one cup.','The cover stopped all cooling because one temperature fell less.'],0,'通过：过去式、did问句、数据与谨慎结论全部准确。','尚未通过：修复did后的动词原形，并保留数据能支持的结论范围。')
],{subject:'物理与数学',title:'英语 × 实验记录：用一般过去时复述保温对照实验',copy:'读取有盖和无盖两杯水的初温、十分钟后温度与降温差，按测量—控制变量—结果顺序复述；用过去时陈述步骤，用did问句检验结论，并保留数据限制。',labels:['计算两组温降','识别加盖这一变量','用过去时复述并提问'],options:['按时间和变量复述数据，再作有限结论','did后继续使用过去式','只看一组数据就断言唯一原因'],success:'完成：控制变量实验产生可比较数据，数学温差量化结果，英语一般过去时准确记录已完成的步骤与发现。'})
};
const previous=window.StudyMateVerifiedCourses;
window.StudyMateVerifiedCourses={get(bookId,unit,section){return lessons[`${bookId}:${unit}:${section}`]||previous?.get(bookId,unit,section)||null},keys:[...(previous?.keys||[]),...Object.keys(lessons)]};
})();
